// src/components/Dashboard.js
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './Dashboard.css';

const Dashboard = ({ user, token, apiUrl }) => {
  const [stats, setStats] = useState({
    patientsWaiting: 12,
    averageWaitTime: 28,
    currentOccupancy: 85,
    triageLevelCounts: {
      1: 2,
      2: 5,
      3: 8,
      4: 15,
      5: 6
    }
  });
  
  // In a real application, we would fetch these stats from the API
  // For demo purposes, we're using static data
  
  // Calculate current date/time for display
  const now = new Date();
  const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
  const timeOptions = { hour: '2-digit', minute: '2-digit' };
  
  const formattedDate = now.toLocaleDateString('en-US', dateOptions);
  const formattedTime = now.toLocaleTimeString('en-US', timeOptions);
  
  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <div className="welcome-message">
          <h1>Welcome, {user?.full_name || 'User'}</h1>
          <span className="user-role">{user?.username === 'doctor' ? 'Doctor' : 'Nurse'}</span>
        </div>
        <div className="current-datetime">
          {formattedDate} | {formattedTime}
        </div>
        <div className="quick-actions">
          <Link to="/patient/new" className="action-button primary">
            New Patient
          </Link>
          <Link to="/queue" className="action-button secondary">
            View Queue
          </Link>
        </div>
      </div>
      
      {/* Rest of your Dashboard component code... */}
    </div>
  );
};

export default Dashboard;
